#[program]
pub mod solana_pa_prototype {
    use super::*;

    /// Initialize a new PAState account.
    ///
    /// remaining_accounts[0]: genesis root marker PDA (REQUIRED - will be created)
    ///
    /// The genesis root marker is required so that transactions built against the
    /// initial empty tree remain valid after subsequent transactions update the root.
    pub fn initialize<'info>(ctx: Context<'_, '_, '_, 'info, Initialize<'info>>) -> Result<()> {
        // Genesis root marker is required
        require!(
            !ctx.remaining_accounts.is_empty(),
            PAError::InvalidTransactionData
        );

        // Get key before taking mutable reference
        let pa_state_key = ctx.accounts.pa_state.key();

        let state = &mut ctx.accounts.pa_state;
        state.bump = ctx.bumps.pa_state;
        state.authority = ctx.accounts.payer.key();
        state.paused = false;

        // Initialize variable-depth tree at depth 1 (capacity = 2 leaves)
        state.current_depth = INITIAL_TREE_DEPTH as u8;
        state.frontier = vec![PADDING_LEAF.to_bytes()]; // Single entry for depth 1

        // Initialize commitment tree with empty state at depth 1
        // Empty root at depth 1 = ZEROS[0] = PADDING_LEAF
        state.root = EMPTY_TREE_ROOT_INITIAL.to_bytes();
        state.next_index = 0;

        // Initialize expiry config with compile-time defaults
        state.min_expiry_slots = MIN_EXPIRY_SLOTS;
        state.max_expiry_slots = MAX_EXPIRY_SLOTS;

        // Create root marker for genesis root (so historical root check works from start)
        let genesis_root = state.root;
        root::create_root_marker(
            &crate::ID,
            &pa_state_key,
            &genesis_root,
            &ctx.accounts.payer.to_account_info(),
            &ctx.remaining_accounts[0],
            &ctx.accounts.system_program.to_account_info(),
        )?;
        msg!("Created genesis root marker");

        msg!("PAState initialized with empty commitment tree");
        Ok(())
    }

    /// Settle a transaction: verify proofs, update commitment tree, mark nullifiers.
    ///
    /// This is the main entry point for transaction execution.
    ///
    /// # Arguments
    /// * `transaction_data` - Bincode-serialized arm-risc0 Transaction
    pub fn settle<'info>(
        ctx: Context<'_, '_, '_, 'info, Settle<'info>>,
        transaction_data: Vec<u8>,
    ) -> Result<()> {
        require!(!ctx.accounts.pa_state.paused, PAError::Paused);

        let tx: Transaction = bincode::deserialize(&transaction_data)
            .map_err(|_| error!(PAError::InvalidTransactionData))?;

        let pa_state_key = ctx.accounts.pa_state.key();
        let pa_state_info = ctx.accounts.pa_state.to_account_info();
        let payer = ctx.accounts.authority.to_account_info();

        execute_settlement(
            &mut ctx.accounts.pa_state,
            &pa_state_info,
            &tx,
            ctx.remaining_accounts,
            &payer,
            &pa_state_key,
            &ctx.accounts.system_program.to_account_info(),
            &ctx.accounts.verifier_router_program.to_account_info(),
            &ctx.accounts.router.to_account_info(),
            &ctx.accounts.verifier_entry.to_account_info(),
            &ctx.accounts.verifier_program.to_account_info(),
        )?;

        msg!("Settlement complete");
        Ok(())
    }

    /// Initialize a TxData account for chunked upload.
    ///
    /// # Arguments
    /// * `upload_id` - Unique identifier for this upload (client-provided, e.g. timestamp)
    /// * `capacity` - Size of payload buffer to allocate
    /// * `expires_slot` - Slot after which this TxData expires
    pub fn txdata_init(
        ctx: Context<TxDataInit>,
        upload_id: u64,
        capacity: u32,
        expires_slot: u64,
    ) -> Result<()> {
        // Validate expiry bounds using configurable values from PAState
        let clock = Clock::get()?;
        let pa_state = &ctx.accounts.pa_state;
        let min_expires = clock.slot.saturating_add(pa_state.get_min_expiry_slots());
        let max_expires = clock.slot.saturating_add(pa_state.get_max_expiry_slots());

        require!(expires_slot >= min_expires, PAError::TxDataExpiryTooSoon);
        require!(expires_slot <= max_expires, PAError::TxDataExpiryTooLate);

        let txdata = &mut ctx.accounts.tx_data;
        txdata.bump = ctx.bumps.tx_data;
        txdata.authority = ctx.accounts.authority.key();
        txdata.refund = ctx.accounts.authority.key();
        txdata.written_len = 0;
        txdata.expires_slot = expires_slot;
        txdata.payload = vec![0u8; capacity as usize];

        msg!(
            "TxData initialized: upload_id={}, capacity={}, expires_slot={}",
            upload_id,
            capacity,
            expires_slot
        );
        Ok(())
    }

    /// Write a chunk to TxData.
    #[allow(unused_variables)]
    pub fn txdata_write(
        ctx: Context<TxDataWrite>,
        upload_id: u64,
        offset: u32,
        data: Vec<u8>,
    ) -> Result<()> {
        let txdata = &mut ctx.accounts.tx_data;

        // Check expiry before allowing write
        let clock = Clock::get()?;
        if clock.slot > txdata.expires_slot {
            return Err(error!(PAError::TxDataExpired));
        }

        let end = offset as usize + data.len();
        require!(end <= txdata.payload.len(), PAError::TxDataBoundsExceeded);

        txdata.payload[offset as usize..end].copy_from_slice(&data);
        txdata.written_len = std::cmp::max(txdata.written_len, end as u32);

        msg!("TxData write: {} bytes at offset {}", data.len(), offset);
        Ok(())
    }

    /// Close a TxData account and reclaim rent.
    /// Authority can close at any time (not just after expiration).
    #[allow(unused_variables)]
    pub fn txdata_close(ctx: Context<TxDataClose>, upload_id: u64) -> Result<()> {
        // Account closure is handled by Anchor's close constraint
        msg!("TxData closed: upload_id={}", upload_id);
        Ok(())
    }

    /// Extend the expiration deadline of a TxData account.
    ///
    /// Allows the authority to extend expiration even after the original deadline passed.
    /// New expiry must be within [current_slot + min, current_slot + max] bounds.
    #[allow(unused_variables)]
    pub fn txdata_extend(
        ctx: Context<TxDataExtend>,
        upload_id: u64,
        new_expires_slot: u64,
    ) -> Result<()> {
        let clock = Clock::get()?;
        let pa_state = &ctx.accounts.pa_state;
        let txdata = &mut ctx.accounts.tx_data;

        // Validate new expiry is within bounds from current slot
        let min_expires = clock.slot.saturating_add(pa_state.get_min_expiry_slots());
        let max_expires = clock.slot.saturating_add(pa_state.get_max_expiry_slots());

        require!(
            new_expires_slot >= min_expires,
            PAError::TxDataExpiryTooSoon
        );
        require!(
            new_expires_slot <= max_expires,
            PAError::TxDataExpiryTooLate
        );

        // New expiry must be strictly greater than current (prevent no-op or shortening)
        require!(
            new_expires_slot > txdata.expires_slot,
            PAError::TxDataExtendMustIncrease
        );

        let old_expires = txdata.expires_slot;
        txdata.expires_slot = new_expires_slot;

        msg!(
            "TxData extended: upload_id={}, old_expires={}, new_expires={}",
            upload_id,
            old_expires,
            new_expires_slot
        );
        Ok(())
    }

    /// Close an EXPIRED TxData account and reclaim rent.
    ///
    /// Anyone can call this for garbage collection of stale accounts.
    /// Rent goes to the `refund` address stored in the account.
    /// Only works if current_slot > expires_slot.
    #[allow(unused_variables)]
    pub fn txdata_close_expired(
        ctx: Context<TxDataCloseExpired>,
        upload_id: u64,
        authority: Pubkey,
    ) -> Result<()> {
        let clock = Clock::get()?;
        let txdata = &ctx.accounts.tx_data;

        // CRITICAL: Only allow close if expired
        require!(clock.slot > txdata.expires_slot, PAError::TxDataNotExpired);

        // Account closure is handled by Anchor's close constraint
        msg!(
            "Expired TxData closed: upload_id={}, expires_slot={}, current_slot={}",
            upload_id,
            txdata.expires_slot,
            clock.slot
        );
        Ok(())
    }

    /// Update TxData expiry configuration.
    ///
    /// Only the protocol authority can call this.
    pub fn update_expiry_config(
        ctx: Context<UpdateExpiryConfig>,
        new_min_expiry_slots: u64,
        new_max_expiry_slots: u64,
    ) -> Result<()> {
        // Validate: min < max
        require!(
            new_min_expiry_slots < new_max_expiry_slots,
            PAError::InvalidExpiryConfig
        );

        // Validate: reasonable minimum (at least 10 slots ~4 seconds)
        require!(new_min_expiry_slots >= 10, PAError::InvalidExpiryConfig);

        // Validate: reasonable maximum (no more than ~7 days)
        const SEVEN_DAYS_SLOTS: u64 = 7 * 24 * 60 * 60 * 1000 / 400; // ~1.5M slots
        require!(
            new_max_expiry_slots <= SEVEN_DAYS_SLOTS,
            PAError::InvalidExpiryConfig
        );

        let state = &mut ctx.accounts.pa_state;
        let old_min = state.min_expiry_slots;
        let old_max = state.max_expiry_slots;

        state.min_expiry_slots = new_min_expiry_slots;
        state.max_expiry_slots = new_max_expiry_slots;

        msg!(
            "Expiry config updated: min {} -> {}, max {} -> {}",
            old_min,
            new_min_expiry_slots,
            old_max,
            new_max_expiry_slots
        );
        Ok(())
    }

    /// Execute settlement from a TxData account.
    #[allow(unused_variables)]
    pub fn settle_from_txdata<'info>(
        ctx: Context<'_, '_, '_, 'info, SettleFromTxData<'info>>,
        upload_id: u64,
    ) -> Result<()> {
        require!(!ctx.accounts.pa_state.paused, PAError::Paused);

        let txdata = &ctx.accounts.tx_data;

        // Check expiry
        let clock = Clock::get()?;
        if clock.slot > txdata.expires_slot {
            return Err(error!(PAError::TxDataExpired));
        }

        let tx: Transaction = bincode::deserialize(&txdata.payload[..txdata.written_len as usize])
            .map_err(|_| error!(PAError::InvalidTransactionData))?;

        let pa_state_key = ctx.accounts.pa_state.key();
        let pa_state_info = ctx.accounts.pa_state.to_account_info();
        let payer = ctx.accounts.authority.to_account_info();

        execute_settlement(
            &mut ctx.accounts.pa_state,
            &pa_state_info,
            &tx,
            ctx.remaining_accounts,
            &payer,
            &pa_state_key,
            &ctx.accounts.system_program.to_account_info(),
            &ctx.accounts.verifier_router_program.to_account_info(),
            &ctx.accounts.router.to_account_info(),
            &ctx.accounts.verifier_entry.to_account_info(),
            &ctx.accounts.verifier_program.to_account_info(),
        )?;

        msg!("Settlement from TxData complete");
        Ok(())
    }

    /// Emergency stop - permanently pause the protocol.
    ///
    /// Once paused, the protocol cannot be unpaused without a program upgrade.
    /// This matches EVM Protocol Adapter behavior (one-way emergency stop).
    pub fn emergency_stop(ctx: Context<EmergencyStop>) -> Result<()> {
        let state = &mut ctx.accounts.pa_state;
        require!(!state.paused, PAError::AlreadyPaused);
        state.paused = true;
        msg!(
            "Emergency stop activated by {}",
            ctx.accounts.authority.key()
        );
        Ok(())
    }

    /// Transfer authority to a new account.
    ///
    /// This is equivalent to EVM Protocol Adapter's `transferOwnership()`.
    /// Single-step transfer (no pending/accept pattern) for EVM parity.
    pub fn transfer_authority(
        ctx: Context<TransferAuthority>,
        new_authority: Pubkey,
    ) -> Result<()> {
        let state = &mut ctx.accounts.pa_state;
        let old_authority = state.authority;
        state.authority = new_authority;
        msg!(
            "Authority transferred from {} to {}",
            old_authority,
            new_authority
        );
        Ok(())
    }
}

