/// Append a single commitment to the tree using frontier-based append.
/// Grows the tree when capacity is reached.
fn append_to_tree(state: &mut PAStateAccount, leaf: Digest) -> Result<()> {
    // Check if we need to grow the tree before this append
    if state.needs_growth() {
        if !state.can_grow() {
            return Err(error!(PAError::TreeMaxDepthReached));
        }
        let current_root = compute_root_from_frontier(state);
        let new_level = state.grow();
        state.set_frontier(new_level, current_root);
    }

    let mut current = leaf;
    let mut index = state.next_index;
    let depth = state.depth();

    for level in 0..depth {
        if index & 1 == 0 {
            // Left child - store in frontier and return
            state.set_frontier(level, current);
            state.next_index += 1;
            return Ok(());
        }
        // Right child - hash with frontier and continue up
        let left = state.get_frontier(level);
        current = hash_two(&left, &current);
        index >>= 1;
    }

    state.next_index += 1;
    Ok(())
}

/// Compute the current root from the frontier.
/// Uses precomputed ZEROS array to avoid expensive on-chain hash computation.
/// Operates over the current tree depth (variable, 1-32).
pub fn compute_root_from_frontier(state: &PAStateAccount) -> Digest {
    let depth = state.depth();

    if state.next_index == 0 {
        // Empty tree root at current depth = ZEROS[depth - 1]
        return ZEROS[depth - 1];
    }

    let mut current = ZEROS[0];
    let mut index = state.next_index;

    for (level, zero) in ZEROS.iter().enumerate().take(depth) {
        if index & 1 == 1 {
            current = hash_two(&state.get_frontier(level), &current);
        } else {
            current = hash_two(&current, zero);
        }
        index >>= 1;
    }
    current
}

/// Calculate minimum tree depth required for final_next_index leaves.
/// Returns depth such that 2^depth >= final_next_index.
pub fn required_depth_for_leaves(final_next_index: u64) -> usize {
    if final_next_index == 0 {
        return INITIAL_TREE_DEPTH;
    }
    // ceil(log2(final_next_index))
    let bits = 64 - (final_next_index - 1).leading_zeros();
    (bits as usize).max(INITIAL_TREE_DEPTH)
}

/// Conditionally reallocate PAState if tree growth is needed.
/// Only transfers lamports and resizes when required_depth > current_depth.
fn maybe_grow_account<'info>(
    pa_state_info: &AccountInfo<'info>,
    state: &PAStateAccount,
    num_commitments: usize,
    payer: &AccountInfo<'info>,
    system_program: &AccountInfo<'info>,
) -> Result<()> {
    let final_next_index = state.next_index.saturating_add(num_commitments as u64);
    let required_depth = required_depth_for_leaves(final_next_index);

    // Cap at MAX_TREE_DEPTH (append_to_tree will error if exceeded)
    let target_depth = required_depth.min(MAX_TREE_DEPTH);

    if target_depth <= state.depth() {
        return Ok(()); // No growth needed
    }

    let new_size = PAStateAccount::space_for_depth(target_depth);
    let rent = Rent::get()?;
    let new_minimum_balance = rent.minimum_balance(new_size);
    let current_balance = pa_state_info.lamports();

    // Transfer additional lamports if needed (before realloc)
    if new_minimum_balance > current_balance {
        let lamports_needed = new_minimum_balance - current_balance;
        anchor_lang::system_program::transfer(
            CpiContext::new(
                system_program.clone(),
                anchor_lang::system_program::Transfer {
                    from: payer.clone(),
                    to: pa_state_info.clone(),
                },
            ),
            lamports_needed,
        )?;
    }

    // Resize the account data
    pa_state_info.resize(new_size)?;

    msg!(
        "Reallocated PAState: depth {} -> {}",
        state.depth(),
        target_depth
    );
    Ok(())
}

/// Call verifier_router::verify via typed CPI.
/// Uses Anchor's generated CPI interface for type safety.
#[allow(clippy::too_many_arguments)]
fn call_verifier_router<'info>(
    verifier_router_program: &AccountInfo<'info>,
    router: &AccountInfo<'info>,
    verifier_entry: &AccountInfo<'info>,
    verifier_program: &AccountInfo<'info>,
    system_program: &AccountInfo<'info>,
    seal: verifier_router::Seal,
    image_id: [u8; 32],
    journal_digest: [u8; 32],
) -> Result<()> {
    let cpi_accounts = verifier_router::cpi::accounts::Verify {
        router: router.clone(),
        verifier_entry: verifier_entry.clone(),
        verifier_program: verifier_program.clone(),
        system_program: system_program.clone(),
    };
    let cpi_ctx = CpiContext::new(verifier_router_program.clone(), cpi_accounts);
    verifier_router::cpi::verify(cpi_ctx, seal, image_id, journal_digest)
}

/// Shared settlement logic for both settle and settle_from_txdata.
#[allow(clippy::too_many_arguments)]
fn execute_settlement<'info>(
    state: &mut PAStateAccount,
    pa_state_info: &AccountInfo<'info>,
    tx: &Transaction,
    remaining_accounts: &[AccountInfo<'info>],
    payer: &AccountInfo<'info>,
    pa_state_key: &Pubkey,
    system_program: &AccountInfo<'info>,
    verifier_router_program: &AccountInfo<'info>,
    router: &AccountInfo<'info>,
    verifier_entry: &AccountInfo<'info>,
    verifier_program: &AccountInfo<'info>,
) -> Result<()> {
    use crate::encoding::{compute_action_tree_root, extract_tags_and_logic_refs};
    // 1) State anchor check (supports historical roots)
    for (action_idx, action) in tx.actions.iter().enumerate() {
        for (cu_idx, cu) in action.compliance_units.iter().enumerate() {
            msg!(
                "Parsing compliance instance: action={}, cu={}",
                action_idx,
                cu_idx
            );
            // Check if root is valid (current, PADDING_LEAF, or historical marker exists)
            if !root::is_root_valid(
                state,
                pa_state_key,
                &cu.instance.consumed_commitment_tree_root,
                remaining_accounts,
            ) {
                return Err(error!(PAError::NonExistingRoot));
            }
        }
    }

    // 2) Extract nullifiers from compliance instances (for PDA creation)
    let mut nullifiers = Vec::new();
    for (action_idx, action) in tx.actions.iter().enumerate() {
        for (cu_idx, cu) in action.compliance_units.iter().enumerate() {
            msg!("Extracting nullifier: action={}, cu={}", action_idx, cu_idx);
            nullifiers.push(cu.instance.consumed_nullifier.to_bytes());
        }
    }

    // 2.5) Pre-compute action data (tags, logic_refs, action_tree_root) for each action.
    // This data is used by ActionExecuted/TransactionExecuted events.
    struct ActionData {
        tags: Vec<types::Digest>,
        logic_refs: Vec<types::Digest>,
        action_tree_root: types::Digest,
    }
    let mut action_data: Vec<ActionData> = Vec::with_capacity(tx.actions.len());
    for (action_idx, action) in tx.actions.iter().enumerate() {
        msg!("Computing action data: action={}", action_idx);
        let (tags, logic_refs) = extract_tags_and_logic_refs(action)
            .map_err(|_| error!(PAError::InvalidTransactionData))?;
        let action_tree_root =
            compute_action_tree_root(&tags).map_err(|_| error!(PAError::InvalidTransactionData))?;
        action_data.push(ActionData {
            tags,
            logic_refs,
            action_tree_root,
        });
    }

    // 3) Verify proofs (aggregated or individual)
    let is_aggregated = tx.aggregation_proof.is_some();

    if is_aggregated {
        // Aggregated path: batch aggregation proof
        msg!("Preparing aggregated proof for verification");
        let prepared =
            prepare_proof_for_verification(tx).map_err(|_| error!(PAError::InvalidProof))?;

        msg!("Verifying aggregated proof via verifier_router");
        call_verifier_router(
            verifier_router_program,
            router,
            verifier_entry,
            verifier_program,
            system_program,
            prepared.seal,
            prepared.image_id,
            prepared.journal_digest,
        )
        .map_err(|_| error!(PAError::VerifierRouterFailed))?;
        msg!("Aggregated proof verification passed");
    } else {
        return Err(error!(PAError::AggregationRequired));
    }

    // 3.5) Verify delta proof (balance conservation)
    // Uses Solana syscalls (secp256k1_recover, hashv) for optimal CU usage.
    delta::verify_delta_proof(tx)?;

    // 3.6) Emit app data events and EVM parity events for indexing
    // NOTE: AppData for events/external calls is read from transaction fields directly.
    // Proof verification is bound to `instance_journal` bytes via aggregation digest.
    // This split is intentional and matches the EVM PA assumption model.
    // Only payloads with deletion_criterion == Never are emitted (matches EVM PA).
    let mut all_tags: Vec<[u8; 32]> = Vec::new();
    let mut all_logic_refs: Vec<[u8; 32]> = Vec::new();

    for (action, data) in tx.actions.iter().zip(action_data.iter()) {
        // Emit app data events
        for lvi in &action.logic_verifier_inputs {
            emit_app_data_events(&lvi.tag, &lvi.app_data);
        }

        // Emit ActionExecuted event (EVM parity) using precomputed data
        emit!(ActionExecutedEvent {
            action_tree_root: data.action_tree_root.to_bytes(),
            action_tag_count: data.tags.len() as u32,
        });

        // Accumulate for TransactionExecuted
        all_tags.extend(data.tags.iter().map(|d| d.to_bytes()));
        all_logic_refs.extend(data.logic_refs.iter().map(|d| d.to_bytes()));
    }

    // Execute external calls (after proof verification, before state updates)
    // Uses `logic_verifier_inputs.app_data.external_payload` as the execution source.
    // On-chain journal decoding/cross-checking is intentionally not performed.
    // This ensures external call failures don't leave state partially updated
    #[cfg(not(test))]
    {
        external_calls::execute_external_calls(tx, remaining_accounts, nullifiers.len()).map_err(
            |e| match e {
                PAError::ExternalCallOutputMismatch => error!(PAError::ExternalCallOutputMismatch),
                PAError::UnregisteredForwarder => error!(PAError::UnregisteredForwarder),
                PAError::ExternalCallCpiFailed => error!(PAError::ExternalCallCpiFailed),
                PAError::InvalidExternalCallBlob => error!(PAError::InvalidExternalCallBlob),
                _ => error!(PAError::ExternalCallCpiFailed),
            },
        )?;
    }

    // Emit TransactionExecuted event (EVM parity)
    emit!(TransactionExecutedEvent {
        tags: all_tags,
        logic_refs: all_logic_refs,
    });

    // 4) Nullifier PDA creation via remaining_accounts
    // remaining_accounts layout: [nullifier_pda_0, ..., nullifier_pda_n, ...additional CPI accounts...]
    if !nullifiers.is_empty() {
        require!(
            remaining_accounts.len() >= nullifiers.len(),
            PAError::InvalidTransactionData
        );

        for (i, nullifier_bytes) in nullifiers.iter().enumerate() {
            let marker = &remaining_accounts[i];
            nullifier::check_and_create_nullifier_marker(
                &crate::ID,
                pa_state_key,
                nullifier_bytes,
                payer,
                marker,
                system_program,
            )?;
        }
        msg!("Created {} nullifier PDAs", nullifiers.len());
    }

    // Append commitments
    let commitments =
        settle::extract_commitments(tx).map_err(|_| error!(PAError::InvalidTransactionData))?;
    maybe_grow_account(
        pa_state_info,
        state,
        commitments.len(),
        payer,
        system_program,
    )?;
    for commitment in commitments {
        append_to_tree(state, commitment)?;
    }

    // Update root
    let new_root = compute_root_from_frontier(state).to_bytes();
    state.root = new_root;

    // Create root marker for the new root (enables parallel tx construction)
    // Layout: remaining_accounts = [nullifier PDAs..., external call accounts..., historical root markers..., new root marker PDA]
    // The new root marker is always at the LAST position to avoid conflicting with external call layout
    if !remaining_accounts.is_empty() {
        let root_marker_index = remaining_accounts.len() - 1;
        // Only create if the last account is the expected PDA (caller must provide it)
        let (expected_pda, _) = root::derive_root_marker_pda(&crate::ID, pa_state_key, &new_root);
        if remaining_accounts[root_marker_index].key == &expected_pda {
            root::create_root_marker(
                &crate::ID,
                pa_state_key,
                &new_root,
                payer,
                &remaining_accounts[root_marker_index],
                system_program,
            )?;
            msg!("Created root marker for new root");
        }
    }

    Ok(())
}

