#[derive(Accounts)]
pub struct Initialize<'info> {
    #[account(
        init,
        payer = payer,
        space = PAStateAccount::INITIAL_SPACE, // Variable-depth tree starts at depth 1
        seeds = [PA_STATE_SEED],
        bump
    )]
    pub pa_state: Account<'info, PAStateAccount>,

    #[account(mut)]
    pub payer: Signer<'info>,

    pub system_program: Program<'info, System>,
}

#[derive(Accounts)]
pub struct EmergencyStop<'info> {
    #[account(
        mut,
        seeds = [PA_STATE_SEED],
        bump = pa_state.bump,
        has_one = authority @ PAError::Unauthorized,
    )]
    pub pa_state: Account<'info, PAStateAccount>,

    pub authority: Signer<'info>,
}

#[derive(Accounts)]
pub struct TransferAuthority<'info> {
    #[account(
        mut,
        seeds = [PA_STATE_SEED],
        bump = pa_state.bump,
        has_one = authority @ PAError::Unauthorized,
    )]
    pub pa_state: Account<'info, PAStateAccount>,

    pub authority: Signer<'info>,
}

#[derive(Accounts)]
pub struct Settle<'info> {
    #[account(
        mut,
        seeds = [PA_STATE_SEED],
        bump = pa_state.bump,
    )]
    pub pa_state: Account<'info, PAStateAccount>,

    #[account(mut)]
    pub authority: Signer<'info>,
    pub system_program: Program<'info, System>,

    /// CHECK: Verified via address constraint.
    #[account(address = VERIFIER_ROUTER_ID)]
    pub verifier_router_program: UncheckedAccount<'info>,

    /// CHECK: Router state PDA - validated by verifier_router during CPI.
    pub router: UncheckedAccount<'info>,

    /// CHECK: Verifier entry PDA - validated by verifier_router during CPI.
    pub verifier_entry: UncheckedAccount<'info>,

    /// CHECK: The groth16 verifier program - validated by verifier_router.
    pub verifier_program: UncheckedAccount<'info>,
}

#[derive(Accounts)]
#[instruction(upload_id: u64)]
pub struct SettleFromTxData<'info> {
    #[account(
        mut,
        seeds = [PA_STATE_SEED],
        bump = pa_state.bump,
    )]
    pub pa_state: Account<'info, PAStateAccount>,

    #[account(
        seeds = [TX_DATA_SEED, authority.key().as_ref(), &upload_id.to_le_bytes()],
        bump = tx_data.bump,
        has_one = authority
    )]
    pub tx_data: Account<'info, TxDataAccount>,

    #[account(mut)]
    pub authority: Signer<'info>,
    pub system_program: Program<'info, System>,

    /// CHECK: Verified via address constraint.
    #[account(address = VERIFIER_ROUTER_ID)]
    pub verifier_router_program: UncheckedAccount<'info>,

    /// CHECK: Router state PDA - validated by verifier_router during CPI.
    pub router: UncheckedAccount<'info>,

    /// CHECK: Verifier entry PDA - validated by verifier_router during CPI.
    pub verifier_entry: UncheckedAccount<'info>,

    /// CHECK: The groth16 verifier program - validated by verifier_router.
    pub verifier_program: UncheckedAccount<'info>,
    // remaining_accounts: nullifier PDAs + external call accounts
}

#[derive(Accounts)]
#[instruction(upload_id: u64, capacity: u32)]
pub struct TxDataInit<'info> {
    /// PAState for reading configurable expiry bounds.
    #[account(seeds = [PA_STATE_SEED], bump = pa_state.bump)]
    pub pa_state: Account<'info, PAStateAccount>,

    #[account(
        init,
        payer = authority,
        space = TxDataAccount::space(capacity as usize),
        seeds = [TX_DATA_SEED, authority.key().as_ref(), &upload_id.to_le_bytes()],
        bump
    )]
    pub tx_data: Account<'info, TxDataAccount>,

    #[account(mut)]
    pub authority: Signer<'info>,

    pub system_program: Program<'info, System>,
}

#[derive(Accounts)]
#[instruction(upload_id: u64)]
pub struct TxDataWrite<'info> {
    #[account(
        mut,
        seeds = [TX_DATA_SEED, authority.key().as_ref(), &upload_id.to_le_bytes()],
        bump = tx_data.bump,
        has_one = authority
    )]
    pub tx_data: Account<'info, TxDataAccount>,

    pub authority: Signer<'info>,
}

#[derive(Accounts)]
#[instruction(upload_id: u64)]
pub struct TxDataClose<'info> {
    #[account(
        mut,
        seeds = [TX_DATA_SEED, authority.key().as_ref(), &upload_id.to_le_bytes()],
        bump = tx_data.bump,
        has_one = authority,
        close = refund
    )]
    pub tx_data: Account<'info, TxDataAccount>,

    pub authority: Signer<'info>,

    /// CHECK: Receives the rent refund. Must match tx_data.refund.
    #[account(mut, address = tx_data.refund)]
    pub refund: UncheckedAccount<'info>,
}

#[derive(Accounts)]
#[instruction(upload_id: u64)]
pub struct TxDataExtend<'info> {
    /// PAState for reading configurable expiry bounds.
    #[account(seeds = [PA_STATE_SEED], bump = pa_state.bump)]
    pub pa_state: Account<'info, PAStateAccount>,

    #[account(
        mut,
        seeds = [TX_DATA_SEED, authority.key().as_ref(), &upload_id.to_le_bytes()],
        bump = tx_data.bump,
        has_one = authority
    )]
    pub tx_data: Account<'info, TxDataAccount>,

    pub authority: Signer<'info>,
}

#[derive(Accounts)]
#[instruction(upload_id: u64, authority: Pubkey)]
pub struct TxDataCloseExpired<'info> {
    #[account(
        mut,
        seeds = [TX_DATA_SEED, authority.as_ref(), &upload_id.to_le_bytes()],
        bump = tx_data.bump,
        close = refund
    )]
    pub tx_data: Account<'info, TxDataAccount>,

    /// Anyone can call, pays tx fee.
    pub payer: Signer<'info>,

    /// CHECK: Receives the rent refund. Must match tx_data.refund.
    #[account(mut, address = tx_data.refund)]
    pub refund: UncheckedAccount<'info>,
}

#[derive(Accounts)]
pub struct UpdateExpiryConfig<'info> {
    #[account(
        mut,
        seeds = [PA_STATE_SEED],
        bump = pa_state.bump,
        has_one = authority @ PAError::Unauthorized
    )]
    pub pa_state: Account<'info, PAStateAccount>,

    pub authority: Signer<'info>,
}

// =============================================================================
// App Data Events
// =============================================================================

/// Resource payload event - emitted for resource data blobs.
#[event]
pub struct ResourcePayloadEvent {
    pub tag: [u8; 32],
    pub index: u32,
    pub blob: Vec<u8>,
}

/// Discovery payload event - emitted for public key discovery data.
#[event]
pub struct DiscoveryPayloadEvent {
    pub tag: [u8; 32],
    pub index: u32,
    pub blob: Vec<u8>,
}

/// External payload event - emitted for external call data.
#[event]
pub struct ExternalPayloadEvent {
    pub tag: [u8; 32],
    pub index: u32,
    pub blob: Vec<u8>,
}

/// Application payload event - emitted for application-specific data.
#[event]
pub struct ApplicationPayloadEvent {
    pub tag: [u8; 32],
    pub index: u32,
    pub blob: Vec<u8>,
}

// =============================================================================
// EVM Parity Events
// =============================================================================

/// Action executed event - emitted after each action is processed.
/// Matches EVM PA's ActionExecuted event.
#[event]
pub struct ActionExecutedEvent {
    pub action_tree_root: [u8; 32],
    pub action_tag_count: u32,
}

/// Transaction executed event - emitted after full transaction settlement.
/// Matches EVM PA's TransactionExecuted event.
#[event]
pub struct TransactionExecutedEvent {
    pub tags: Vec<[u8; 32]>,
    pub logic_refs: Vec<[u8; 32]>,
}

/// Forwarder call executed event - emitted for each external call.
/// Matches EVM PA's ForwarderCallExecuted event.
#[event]
pub struct ForwarderCallExecutedEvent {
    pub forwarder: Pubkey,
    pub input: Vec<u8>,
    pub output: Vec<u8>,
}

/// Deletion criterion constant - only emit payloads marked as "Never" delete.
const DELETION_CRITERION_NEVER: u32 = 1;

/// Emit app data events for a logic verifier input.
/// Only emits payloads with deletion_criterion == Never (matching EVM PA behavior).
fn emit_app_data_events(tag: &types::Digest, app_data: &types::AppData) {
    use encoding::words_to_bytes;
    let tag_bytes = tag.to_bytes();

    // Resource payloads
    for (i, payload) in app_data.resource_payload.iter().enumerate() {
        if payload.deletion_criterion == DELETION_CRITERION_NEVER {
            emit!(ResourcePayloadEvent {
                tag: tag_bytes,
                index: i as u32,
                blob: words_to_bytes(&payload.blob),
            });
        }
    }

    // Discovery payloads
    for (i, payload) in app_data.discovery_payload.iter().enumerate() {
        if payload.deletion_criterion == DELETION_CRITERION_NEVER {
            emit!(DiscoveryPayloadEvent {
                tag: tag_bytes,
                index: i as u32,
                blob: words_to_bytes(&payload.blob),
            });
        }
    }

    // External payloads
    for (i, payload) in app_data.external_payload.iter().enumerate() {
        if payload.deletion_criterion == DELETION_CRITERION_NEVER {
            emit!(ExternalPayloadEvent {
                tag: tag_bytes,
                index: i as u32,
                blob: words_to_bytes(&payload.blob),
            });
        }
    }

    // Application payloads
    for (i, payload) in app_data.application_payload.iter().enumerate() {
        if payload.deletion_criterion == DELETION_CRITERION_NEVER {
            emit!(ApplicationPayloadEvent {
                tag: tag_bytes,
                index: i as u32,
                blob: words_to_bytes(&payload.blob),
            });
        }
    }
}
